function shellTeam(){let r=location.hash.slice(1)||'home';const nav=[['home','home','الرئيسية'],['appointments','calendar','المواعيد'],['services','service','الخدمات'],...(admin?[['products','stock','المنتجات']]:[]),...(canStock()?[['supplies','service','كتالوج المواد']]:[])];$('.sidebar nav').innerHTML=nav.map(([url,i,t])=>`<a class="navlink ${r===url||url==='supplies'&&r.startsWith('supply/')||url==='appointments'&&/appointment|session|medical/.test(r)?'active':''}" href="#${url}">${ico(i)}<span>${t}</span></a>`).join('')+(canStock()?`<details class="inventory-dropdown" ${r.startsWith('inventory')?'open':''}><summary class="navlink ${r.startsWith('inventory')?'active':''}" onclick="if(!this.parentElement.open)location.hash='inventory/stock'">${ico('stock')}<span>المخزون</span>${ico('chevron')}</summary><div class="inventory-submenu"><a class="${r==='inventory/count'?'active':''}" href="#inventory/count">الجرد</a><a class="${r==='inventory/history'?'active':''}" href="#inventory/history">السجل</a></div></details><div class="management-section"><small>إدارة العيادة</small><a class="navlink ${r==='admin'?'active':''}" href="#admin">${ico('users')}<span>إدارة العيادة</span></a></div>`:'');$('.sidebar-foot').innerHTML=`Nothing Major<small>${roles[role].title}</small>`;$('.topbar .row').innerHTML=`<span class="demo">نموذج تفاعلي · بيانات تجريبية</span><details class="role-picker"><summary aria-label="تبديل الشخصية"><span class="avatar">${roles[role].initial}</span><span><strong>${roles[role].name}</strong><small>${roles[role].title}</small></span>${ico('chevron')}</summary><div class="role-menu"><small>استكشفي تجربة الفريق</small>${Object.entries(roles).map(([id,r])=>`<button onclick="switchRole('${id}')" class="${id===role?'selected':''}"><span class="avatar">${r.initial}</span><span><strong>${r.name}</strong><small>${r.title}</small></span>${id===role?ico('check'):''}</button>`).join('')}<p>تبديل تجريبي للصلاحيات، دون تسجيل دخول.</p></div></details>`;if(!$('#chatLauncher')){document.body.insertAdjacentHTML('beforeend',`<button id="chatLauncher" aria-label="فتح الدردشة" onclick="toggleChat()">${ico('chat')}</button><aside id="chatPanel" aria-label="دردشة العميلات" hidden></aside>`)}$('#chatLauncher').hidden=false}
function dayAppointments(){return db.appointments.filter(a=>a.date===today&&a.status!=='cancelled')}
function kpiItems(k){const all=dayAppointments();return k==='pending'?db.appointments.filter(a=>a.status==='pending'):k==='today'?all.filter(a=>a.status!=='pending'):k==='remaining'?all.filter(a=>['expected','waiting','session'].includes(a.status)):k==='finished'?all.filter(a=>['checkout','closed'].includes(a.status)):all.filter(a=>a.status===k)}
function toggleKpi(k){openKpi=openKpi===k?'':k;document.querySelectorAll('.overview-card').forEach(card=>{const content=card.querySelector('.overview-content'),isOpen=content.id==='kpi-'+openKpi;card.classList.toggle('is-open',isOpen);card.querySelector('button').setAttribute('aria-expanded',String(isOpen));content.inert=!isOpen;content.setAttribute('aria-hidden',String(!isOpen))})}
function kpis(){const items=role==='doctor'?[['today','مواعيد اليوم','calendar'],['remaining','المواعيد المتبقية','clock']]:[['pending','حجوزات بانتظار التأكيد','calendar'],['waiting','الانتظار','users'],['session','في الجلسة','service'],['checkout','بانتظار الدفع','check']];return `<div class="overview-grid ${role==='doctor'?'two':''}">${items.map(([k,t,i])=>`<div class="overview-card ${openKpi===k?'is-open':''}"><button class="overview-toggle" onclick="toggleKpi('${k}')" aria-expanded="${openKpi===k}" aria-controls="kpi-${k}"><span class="overview-label">${ico(i)}${t}</span><span class="overview-number">${String(kpiItems(k).length).padStart(2,'0')}<span class="disclosure-arrow">${ico('chevron')}</span></span></button><div id="kpi-${k}" class="overview-content" aria-hidden="${openKpi!==k}" ${openKpi!==k?'inert':''}><div>${kpiItems(k).length?kpiItems(k).map(a=>`<a href="#appointment/${a.id}">${esc(a.name)} ${ico('chevron')}</a>`).join(''):'<p>لا توجد أسماء حاليًا</p>'}</div></div></div>`).join('')}</div>`}
function appointmentCard(a){if(['checkout','closed'].includes(a.status))return `<article class="appointment-card compact-finished"><div class="compact-info"><span class="time-chip" dir="ltr">${a.time}</span><a class="patient-name" href="#appointment/${a.id}">${esc(a.name)}</a><span class="compact-service">${esc(a.serviceName||services[a.service].name)}</span></div><div class="compact-actions"><span class="remaining-balance">${a.price>a.paid?'المتبقي '+money(a.price-a.paid):'مدفوع بالكامل'}</span><a class="compact-open" href="#appointment/${a.id}">${a.status==='checkout'?'مراجعة الحساب':'عرض التفاصيل'} ←</a></div></article>`;const blocked=['session','checkout','closed','cancelled'].includes(a.status);return `<article class="appointment-card ${a.status==='closed'?'finished':''}"><div class="card-top"><span class="time-chip">${ico('clock')}<span dir="ltr">${a.time}</span></span></div><div class="patient-line"><span class="avatar">${esc(a.name[0])}</span><div><a href="#appointment/${a.id}" class="patient-name">${esc(a.name)}</a><a class="patient-phone" href="tel:${esc(a.phone)}">${ico('phone')}<span dir="ltr">${esc(a.phone)}</span></a></div></div><div class="card-service">${ico('service')}<span>${esc(a.serviceName||services[a.service].name)}${a.additions?.length?' + '+a.additions.length+' خدمة':''}</span><small>${a.duration||services[a.service].duration} دقيقة</small></div><div class="card-meta"><span class="remaining-balance">${a.price>a.paid?'المتبقي <strong>'+money(Math.max(0,a.price-a.paid))+'</strong>':'مدفوع بالكامل'}</span></div><div class="card-actions">${role==='doctor'?`<button class="primary doctor-start" onclick="${a.status==='session'?`location.hash='session/${a.id}'`:['checkout','closed'].includes(a.status)?`location.hash='appointment/${a.id}'`:`startSession('${a.id}')`}">${ico(a.status==='session'?'clock':'service')}${a.status==='session'?'متابعة الجلسة':['checkout','closed'].includes(a.status)?'عرض ملخص الزيارة':'بدء الجلسة'}</button>`:`<button class="primary" ${a.status!=='expected'?'disabled':''} onclick="checkin('${a.id}')">${ico('check')}${a.status==='waiting'?'تم تسجيل الوصول':'تسجيل الوصول'}</button><div class="card-secondary"><button ${blocked?'disabled':''} onclick="reschedule('${a.id}')">${ico('calendar')}إعادة جدولة</button></div>`}</div></article>`}
home=function(){const list=dayAppointments().filter(a=>a.status!=='pending').sort((a,b)=>(['checkout','closed'].includes(a.status))-(['checkout','closed'].includes(b.status))||a.time.localeCompare(b.time));return `<div class="pagehead"><div><div class="eyebrow">${fmt(today)}</div><h1>${role==='doctor'?'أهلًا د. جيجي':'أهلًا كندر'}، يومكِ بين يديكِ</h1><p>${role==='doctor'?'مساحة هادئة للتركيز على مريضاتك.':'كل ما تحتاجينه لتنظيم مواعيد العيادة.'}</p></div></div>${kpis()}<div class="appointments-heading"><div><h2>مواعيد اليوم <span class="count">${list.length}</span></h2><p>تفاصيل واضحة، والخطوة التالية في مكانها.</p></div><a href="#appointments">عرض التقويم ←</a></div><div class="appointment-grid">${list.filter(a=>!['checkout','closed'].includes(a.status)).map(appointmentCard).join('')||'<div class="empty">لا توجد مواعيد متبقية اليوم.</div>'}</div>`};
booking=function(s=0){if(!canReception())return toast('إنشاء الحجوزات متاح للاستقبال أو وضع الإدارة');originalBooking(s)};
const priorDetail=originalDetail;
detail=function(id){const a=db.appointments.find(a=>a.id===id);if(!a)return '<p>الموعد غير موجود</p>';let html=priorDetail(id).replace('حساب طبيبة فعلي.','قنوات خارجية؛ يمكنك التبديل لجيجي ومتابعة نفس الزيارة.');if(a.status==='pending')html=html.replace('<div class="record appointment-record reception-record">',`<section class="panel pending-detail"><h2>مراجعة طلب الحجز</h2><p>${a.review?'بانتظار مراجعة الطبيبة':a.paid?'العربون مستلم؛ الحجز جاهز للتأكيد':'بانتظار استلام العربون'}</p>${!a.review&&a.paid?btn('تأكيد الحجز',`confirmBooking('${a.id}',${a.version})`,'primary'):''}</section><div class="record appointment-record reception-record">`);if(a.additions?.length)html+=`<section class="panel padded"><h2>الخدمات المضافة من الطبيبة</h2>${a.additions.map(s=>`<p>${esc(s.name)} · ${money(s.price)}</p>`).join('')}</section>`;if(role==='doctor')html=html.replace('<h2>تفاصيل الموعد</h2>',`<h2>تفاصيل الموعد</h2><a href="#medical/${id}">فتح الملف الطبي ←</a>`);return html};
function medicalFor(a){return db.medical[a.phone]||{dob:'',email:'',identifier:'',conditions:'',allergies:'',medications:'',notes:'',consultation:!a.review,assessment:!a.review,consent:!a.review}}
function doctorDetail(a){return detail(a.id)}
function medicalPage(id){const a=db.appointments.find(a=>a.id===id);if(!a)return '<p>الملف غير موجود</p>';const m=medicalFor(a);return `<a href="#appointment/${id}">→ العودة للموعد</a>${head('الملف الطبي',esc(a.name),false)}<form class="panel padded medical-form" onsubmit="saveMedical(event,'${id}',${a.version})"><h2>بيانات المريضة</h2><div class="formgrid">${inputField('تاريخ الميلاد','dob',m.dob,'date')}${inputField('البريد الإلكتروني','email',m.email,'email')}${inputField('معرّف الملف التجريبي','identifier',m.identifier)}${inputField('حالات صحية','conditions',m.conditions)}${inputField('حساسية معروفة','allergies',m.allergies)}${inputField('الأدوية الحالية','medications',m.medications)}<label class="wide">ملاحظات الطبيبة<textarea name="notes" rows="4">${esc(m.notes)}</textarea></label></div><h2 class="section">المراجعة الطبية</h2><div class="clinical-checks">${[['consultation','تم توثيق الاستشارة'],['assessment','تم التقييم الطبي'],['consent','تم توثيق الموافقة']].map(([k,t])=>`<label><input name="${k}" type="checkbox" ${m[k]?'checked':''}>${t}</label>`).join('')}</div><div class="form-actions"><button class="primary">حفظ الملف والمراجعة</button></div></form>`}
function saveMedical(e,id,v){e.preventDefault();if(role!=='doctor')return;const f=new FormData(e.target),a=db.appointments.find(a=>a.id===id);const m=Object.fromEntries(f);['consultation','assessment','consent'].forEach(k=>m[k]=f.has(k));if(change(id,a=>{db.medical[a.phone]=m;a.review=!(m.consultation&&m.assessment&&m.consent)},'وثقت الملف والمراجعة الطبية',v)){location.hash='appointment/'+id;toast('تم حفظ الملف الطبي')}}
function resolveDecision(id){const a=db.appointments.find(a=>a.id===id);modal('قرار الطبيبة',`<form onsubmit="saveDecision(event,'${id}',${a.version})"><label>القرار<select name="decision"><option>يمكن تقديم العلاج في الوقت المتبقي</option><option>يلزم إعادة الجدولة</option><option>الموافقة على الإلغاء</option></select></label><label>ملاحظات<input name="note" required></label><div class="footer"><button class="primary">اعتماد القرار</button></div></form>`)}
function saveDecision(e,id,v){e.preventDefault();if(role!=='doctor')return;const f=Object.fromEntries(new FormData(e.target));change(id,a=>{a.decisionRequested=false;a.doctorDecision=f.decision;a.note+='\n'+f.decision+' — '+f.note;if(f.decision==='الموافقة على الإلغاء')a.status='cancelled'},'اعتمدت القرار: '+f.decision,v);closeModal();render();toast('تم تسجيل القرار ومشاركته مع الاستقبال')}
function startSession(id){if(role!=='doctor')return;loadLatest();const a=db.appointments.find(a=>a.id===id);if(a.status==='session'){location.hash='session/'+id;return}if(!['expected','waiting'].includes(a.status))return;if(a.review){location.hash='medical/'+id;toast('أكملي المراجعة الطبية أولًا');return}const active=db.appointments.find(x=>x.status==='session'&&x.id!==id&&x.date>=today);if(active){modal('جلسة حالية تحتاج إنهاء',`<p>جلسة ${esc(active.name)} ما زالت مسجلة كجلسة جارية. راجعي الخدمات المقدمة قبل بدء جلسة ${esc(a.name)}.</p><div class="stack"><button class="primary" onclick="finishSession('${active.id}','${id}')">مراجعة وإنهاء الجلسة ثم بدء التالية</button><button onclick="closeModal();location.hash='session/${active.id}'">متابعة الجلسة الحالية</button></div>`);return}if(change(id,a=>{a.status='session';a.startedAt=Date.now();a.duration??=services[a.service].duration;a.sessionNotes??=''},'بدأت الجلسة',a.version)){location.hash='session/'+id;render()}}
function sessionPage(id){const a=db.appointments.find(a=>a.id===id);if(!a||a.status!=='session')return a?doctorDetail(a):'<p>الجلسة غير موجودة</p>';return `<a href="#appointment/${id}">→ تفاصيل الموعد</a><div class="pagehead"><div><div class="eyebrow">مساحة الطبيبة</div><h1>جلستكِ، بكل تركيز</h1><p>${esc(a.name)} · ${esc(a.serviceName||services[a.service].name)}</p></div>${badge(a)}</div><div class="session-layout"><div><section class="timer-surface"><span class="live-indicator">● الجلسة جارية</span><p>الوقت المنقضي</p><div id="liveTimer" data-id="${id}" class="live-timer" dir="ltr">00:00</div><div class="timer-facts"><span>المدة المحددة <strong>${a.duration} دقيقة</strong></span><span>المتبقي <strong id="remainingTimer" dir="ltr">—</strong></span><span>النهاية المتوقعة <strong>${new Date(a.startedAt+a.duration*60000).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</strong></span></div></section><div class="session-tools"><button onclick="extendSession('${id}')">${ico('clock')}تمديد الوقت</button><button onclick="addSessionService('${id}')">${ico('service')}إضافة خدمة</button></div><button class="primary finish-session" onclick="finishSession('${id}')">إنهاء الجلسة ومراجعة الحساب ←</button></div><aside><section class="panel padded session-patient-card"><div class="patient-line"><span class="avatar">${esc(a.name[0])}</span><div><h2>${esc(a.name)}</h2><span dir="ltr">${a.phone}</span></div></div><div class="clinical-summary"><h3>معلومات المريضة</h3><small>الحساسية</small><p>${esc(medicalFor(a).allergies)||'لا توجد معلومات مسجلة'}</p><small>الحالات الصحية</small><p>${esc(medicalFor(a).conditions)||'لا توجد معلومات مسجلة'}</p><small>الأدوية</small><p>${esc(medicalFor(a).medications)||'لا توجد معلومات مسجلة'}</p></div><a href="#medical/${id}">عرض الملف الطبي ←</a><div class="session-patient-services"><h3>الخدمات</h3><div class="bill-line"><span>${esc(a.serviceName||services[a.service].name)}</span><span>${money(a.price-(a.additions||[]).reduce((n,s)=>n+s.price,0))}</span></div>${(a.additions||[]).map(s=>`<div class="bill-line"><span>${esc(s.name)}<small>خدمة مضافة · ${s.duration} دقيقة</small></span><span>${money(s.price)}</span></div>`).join('')}<div class="bill-line"><strong>إجمالي الزيارة</strong><strong>${money(a.price)}</strong></div></div><div class="session-patient-account"><h3>حساب الزيارة</h3><div class="bill-line"><span>المدفوع</span>${money(a.paid)}</div><small>المتبقي بعد الخدمات المضافة</small><div class="money">${money(a.price-a.paid)}</div><p class="muted">بعد اعتمادك، يظهر المبلغ لكندر لإتمام الدفع.</p></div></section></aside></div>`}
function tickTimer(){const el=$('#liveTimer');if(!el)return;const a=db.appointments.find(a=>a.id===el.dataset.id);if(!a?.startedAt)return;const elapsed=Math.max(0,Math.floor((Date.now()-a.startedAt)/1000));const format=s=>String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');el.textContent=format(elapsed);$('#remainingTimer').textContent=elapsed>a.duration*60?'تجاوز '+format(elapsed-a.duration*60):format(a.duration*60-elapsed)}setInterval(tickTimer,1000);
function extendSession(id){const a=db.appointments.find(a=>a.id===id);modal('تمديد وقت الجلسة',`<form onsubmit="applyExtension(event,'${id}',${a.version})"><label>الوقت الإضافي<select name="minutes"><option value="15">15 دقيقة</option><option value="30">30 دقيقة</option><option value="45">45 دقيقة</option><option value="60">60 دقيقة</option></select></label><p class="muted">يظهر أثر التمديد على الجدول في سجل الزيارة.</p><div class="footer"><button class="primary">تأكيد التمديد</button></div></form>`)}
function timeConflict(a,extra){const end=new Date(a.startedAt).getTime()+(a.duration+extra)*60000;return db.appointments.find(x=>x.id!==a.id&&x.date===a.date&&['expected','waiting'].includes(x.status)&&new Date(x.date+'T'+x.time+':00+03:00').getTime()<end&&new Date(x.date+'T'+x.time+':00+03:00').getTime()>a.startedAt)}
function applyExtension(e,id,v){e.preventDefault();if(role!=='doctor')return;const mins=+new FormData(e.target).get('minutes'),a=db.appointments.find(a=>a.id===id),overlap=timeConflict(a,mins);if(overlap){toast('التمديد يتداخل مع موعد '+overlap.name+'؛ أعيدي جدولة الموعد أولًا');return}if(change(id,a=>a.duration+=mins,'مددت الجلسة '+mins+' دقيقة',v)){closeModal();render();toast('تم تمديد الوقت')}}
function addSessionService(id){const a=db.appointments.find(a=>a.id===id);modal('إضافة خدمة للجلسة',`<form onsubmit="applyServiceAddition(event,'${id}',${a.version})"><label>الخدمة<select name="service">${services.filter(s=>s.active!==false&&s.availability==='available'&&s.id!==10).map(s=>`<option value="${s.id}">${esc(s.name)} · ${money(s.price)} · ${s.duration} دقيقة</option>`).join('')}</select></label><div class="notice">تُضاف قيمة الخدمة ووقتها إلى الزيارة، ويظهر الرصيد الجديد للاستقبال.</div><div class="footer"><button class="primary">تأكيد إضافة الخدمة</button></div></form>`)}
function applyServiceAddition(e,id,v){e.preventDefault();if(role!=='doctor')return;const s=services[+new FormData(e.target).get('service')],a=db.appointments.find(a=>a.id===id);if(timeConflict(a,s.duration)){toast('الخدمة تتداخل مع الموعد التالي؛ راجعي الجدول أولًا');return}if(change(id,a=>{a.additions??=[];a.additions.push({id:s.id,name:s.name,price:s.price,duration:s.duration});a.price+=s.price;a.duration+=s.duration},'أضافت خدمة '+s.name,v)){closeModal();render();toast('تم تحديث الوقت والحساب')}}
function saveSessionNotes(e,id,v){e.preventDefault();if(role!=='doctor')return;if(change(id,a=>a.sessionNotes=new FormData(e.target).get('notes'),'حفظت ملاحظات الجلسة',v)){render();toast('تم الحفظ')}}
function finishSession(id,nextId=''){const a=db.appointments.find(a=>a.id===id);modal('اعتماد الخدمات وإنهاء الجلسة',`<p>${esc(a.name)}</p><p>${esc(a.serviceName||services[a.service].name)}${(a.additions||[]).map(s=>' + '+esc(s.name)).join('')}</p><div class="bill-line"><span>الإجمالي</span><strong>${money(a.price)}</strong></div><div class="bill-line"><span>المتبقي للتحصيل</span><strong>${money(a.price-a.paid)}</strong></div><form onsubmit="completeSession(event,'${id}',${a.version},'${nextId}')"><label>تعليمات العناية بعد الجلسة<textarea name="aftercare" rows="3">${esc(a.aftercare||'')}</textarea></label><label class="check"><input type="checkbox" name="followup">تحتاج موعد متابعة بقرار الطبيبة</label><div class="footer"><button class="primary">${nextId?'إنهاء الجلسة وبدء التالية':'اعتماد وإرسال للاستقبال'}</button></div></form>`)}
function completeSession(e,id,v,nextId=''){e.preventDefault();if(role!=='doctor')return;const f=new FormData(e.target);if(change(id,a=>{a.status='checkout';a.finishedAt=Date.now();a.aftercare=f.get('aftercare');a.followup=f.has('followup')},'أنهت الجلسة واعتمدت الخدمات النهائية للتحصيل',v)){closeModal();location.hash='home';render();if(nextId){startSession(nextId)}else toast('أصبحت الزيارة جاهزة للدفع في تجربة كندر')}}
function inputField(label,name,value='',type='text',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function inventoryStatus(u){return u.kind==='جهاز'?u.condition:u.expiry&&u.expiry<today?'منتهي الصلاحية':u.qty<=u.min?'مخزون منخفض':u.expiry&&new Date(u.expiry)-new Date(today)<30*86400000?'ينتهي قريبًا':'متوفر'}
function inventoryBadge(u){const s=inventoryStatus(u);return `<span class="badge ${s==='متوفر'||s==='متاح'?'green':s==='منتهي الصلاحية'?'pink':'amber'}">${s}</span>`}
function inventoryNav(active){return `<div class="inventory-tabs">${[['stock','المخزون'],['count','الجرد'],['history','سجل المخزون']].map(([id,t])=>`<a href="#inventory/${id}" class="${active===id?'selected':''}">${t}</a>`).join('')}</div>`}
function stockPage(){const list=db.stock.filter(u=>u.kind!=='جهاز');return head('المخزون','إدارة الكميات، تنبيهات النقص، وتواريخ الصلاحية.',false)+inventoryNav('stock')+`<div class="stock-kpis">${[['إجمالي المواد',list.length,'مادة مسجلة'],['متاحة للاستخدام',list.filter(u=>u.qty>0&&(!u.expiry||u.expiry>=today)).length,'كميات متوفرة بصلاحية سارية'],['تحتاج إعادة طلب',list.filter(u=>u.qty<=u.min).length,'عند حد التنبيه أو أقل'],['تنتهي قريبًا',list.filter(u=>inventoryStatus(u)==='ينتهي قريبًا').length,'خلال 30 يومًا']].map(([t,n,s])=>`<div><small>${t}</small><strong>${n}</strong><small>${s}</small></div>`).join('')}</div><div class="stock-alerts"><button onclick="filterStockStatus('مخزون منخفض')">${ico('stock')}${list.filter(u=>u.qty<=u.min).length} مواد تحتاج إعادة طلب <span>عرض المواد ←</span></button><button onclick="filterStockStatus('منتهي الصلاحية')">${ico('clock')}${list.filter(u=>inventoryStatus(u)==='منتهي الصلاحية').length} مواد منتهية الصلاحية <span>مراجعة ←</span></button></div><form class="panel stock-form" onsubmit="saveStock(event,${db.inventoryRevision})" oninput="markStockDirty()"><div class="section-head"><h2>مواد العيادة</h2><div class="toolbar"><button type="button" id="discardStock" disabled onclick="render()">تجاهل التغييرات</button><button id="saveStockButton" disabled class="primary">حفظ التغييرات</button></div></div><div class="inventory-filters"><label class="grow">البحث في المخزون<input type="search" placeholder="اسم المادة أو رمز المنتج" oninput="stockQuery=this.value;filterStockRows()" value="${esc(stockQuery)}"></label><label>النوع<select onchange="stockType=this.value;filterStockRows()">${['الكل','مستلزمات طبية','مواد استهلاكية'].map(t=>`<option ${t===stockType?'selected':''}>${t}</option>`).join('')}</select></label><label>الحالة<select id="inventoryStatusSelect" onchange="stockFilter=this.value;filterStockRows()">${['الكل','متوفر','مخزون منخفض','ينتهي قريبًا','منتهي الصلاحية'].map(t=>`<option ${t===stockFilter?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="tablewrap"><table class="stock-table"><thead><tr><th>المادة / الرمز</th><th>النوع</th><th>الكمية</th><th>حد التنبيه</th><th>الصلاحية</th><th>الحالة</th></tr></thead><tbody>${list.map(u=>`<tr data-stock-id="${u.id}"><td><strong>${esc(u.name)}</strong><small dir="ltr">${esc(u.sku)}</small></td><td>${u.type}</td><td><input aria-label="الكمية — ${esc(u.name)}" name="qty-${u.id}" type="number" min="0" step="0.01" value="${u.qty}" ${u.variants?.length?'readonly':''} required>${u.variants?.length?`<a class="variant-link" href="#variants/${u.id}">جرد الخيارات</a>`:''}</td><td><input aria-label="حد التنبيه — ${esc(u.name)}" name="min-${u.id}" type="number" min="0" step="0.01" value="${u.min}" required></td><td><input aria-label="الصلاحية — ${esc(u.name)}" name="expiry-${u.id}" type="date" value="${u.expiry}"></td><td>${inventoryBadge(u)}</td></tr>`).join('')}</tbody></table></div><p id="stockEmpty" class="empty" hidden>لا توجد مواد مطابقة.</p><div class="stock-footer"><p class="muted">تُعتمد التغييرات معًا عند الحفظ. استخدمي الجرد لمطابقة الكمية الفعلية.</p>${inputField('سبب التغيير','reason','','text','placeholder="مثل: استلام توريد أو تلف مواد"')}</div></form>`}
function markStockDirty(){if($('#saveStockButton')){$('#saveStockButton').disabled=false;$('#discardStock').disabled=false}}
function filterStockStatus(s){stockFilter=s;if($('#inventoryStatusSelect'))$('#inventoryStatusSelect').value=s;filterStockRows()}
function filterStockRows(){let shown=0;document.querySelectorAll('[data-stock-id]').forEach(row=>{const u=db.stock.find(x=>x.id===row.dataset.stockId);row.hidden=!((u.name+' '+u.sku).toLowerCase().includes(stockQuery.toLowerCase())&&(stockType==='الكل'||u.type===stockType)&&(stockFilter==='الكل'||inventoryStatus(u)===stockFilter));if(!row.hidden)shown++});if($('#stockEmpty'))$('#stockEmpty').hidden=!!shown}
function loadLatest(){const latest=JSON.parse(localStorage.getItem(key)||'null');if(latest)db=latest}
function stockLog(u,before,after,reason){db.stockLog.push({name:u.name,sku:u.sku,before,after,reason,actor:actor(),at:new Date().toISOString()})}
function saveStock(e,revision){e.preventDefault();if(!canStock())return;const f=new FormData(e.target);loadLatest();if(db.inventoryRevision!==revision){toast('تغير المخزون من نافذة أخرى. أعيدي فتح الصفحة قبل الحفظ.');return}let changed=0;db.stock.filter(u=>u.kind!=='جهاز').forEach(u=>{const qty=+f.get('qty-'+u.id),min=+f.get('min-'+u.id),expiry=f.get('expiry-'+u.id);if(qty!==u.qty||min!==u.min||expiry!==u.expiry){stockLog(u,u.qty,qty,f.get('reason')||'تحديث الكمية / حد التنبيه / الصلاحية');Object.assign(u,{qty,min,expiry,version:u.version+1});changed++}});db.inventoryRevision++;save();render();toast(changed?'تم حفظ '+changed+' مواد وتسجيل التغييرات':'لا توجد تغييرات')}
function countPage(){return head('الجرد','مطابقة المخزون الفعلي مع الكميات المسجلة.',false)+inventoryNav('count')+`<div class="count-list">${db.stock.filter(u=>u.kind!=='جهاز').map(u=>`<form class="panel count-item" onsubmit="saveCount(event,'${u.id}',${u.version})"><div><strong>${esc(u.name)}</strong><small>${esc(u.sku)} · المسجل: ${u.qty}</small></div>${u.variants?.length?`<a class="button-link" href="#variants/${u.id}">جرد الخيارات</a>`:inputField('الكمية الفعلية','qty',u.qty,'number','min="0" step="0.01" required')}${inputField('سبب الفرق','reason','','text','placeholder="سبب الفرق إن وجد"')}${!u.variants?.length?'<button class="primary">حفظ الجرد</button>':''}</form>`).join('')}</div>`}
function saveCount(e,id,v){e.preventDefault();if(!canStock())return;const f=new FormData(e.target);loadLatest();const u=db.stock.find(u=>u.id===id);if(u.version!==v)return toast('تغيرت الكمية؛ حدّثي الصفحة قبل الحفظ');const qty=+f.get('qty');if(qty!==u.qty&&!f.get('reason'))return toast('اكتبي سبب فرق الجرد');stockLog(u,u.qty,qty,f.get('reason')||'مطابقة الجرد');u.qty=qty;u.version++;db.inventoryRevision++;save();render();toast('تم حفظ الجرد')}
function variantsPage(id){const u=db.stock.find(x=>x.id===id);return head('جرد الخيارات',esc(u.name),false)+`<form class="panel padded" onsubmit="saveVariants(event,'${id}',${u.version})">${u.variants.map((v,i)=>inputField(v.name,'v'+i,v.qty,'number','min="0" required')).join('')}${inputField('سبب الجرد','reason','','text','required')}<br><button class="primary">حفظ الكميات</button></form>`}
function saveVariants(e,id,v){e.preventDefault();if(!canStock())return;const f=new FormData(e.target);loadLatest();const u=db.stock.find(x=>x.id===id);if(u.version!==v)return toast('تغيرت البيانات؛ أعيدي فتح الصفحة');const before=u.qty;u.variants.forEach((x,i)=>x.qty=+f.get('v'+i));u.qty=u.variants.reduce((n,x)=>n+x.qty,0);u.version++;db.inventoryRevision++;stockLog(u,before,u.qty,f.get('reason'));save();location.hash='inventory/count';toast('تم اعتماد جرد الخيارات')}
function historyPage(){return head('سجل المخزون','كل تغيير موثق، باسم الموظفة ووقت التعديل.',false)+inventoryNav('history')+`<section class="panel tablewrap"><table><thead><tr><th>المادة</th><th>قبل</th><th>بعد</th><th>السبب</th><th>بواسطة</th><th>التاريخ</th></tr></thead><tbody>${db.stockLog.slice().reverse().map(h=>`<tr><td>${esc(h.name)}<small>${esc(h.sku)}</small></td><td>${h.before}</td><td>${h.after}</td><td>${esc(h.reason)}</td><td>${esc(h.actor)}</td><td>${new Date(h.at).toLocaleString('ar-SA-u-ca-gregory-nu-latn')}</td></tr>`).join('')}</tbody></table>${!db.stockLog.length?'<div class="empty">لا توجد تغييرات بعد. ستظهر عمليات الحفظ والجرد هنا.</div>':''}</section>`}
function suppliesPage(){return `<div class="pagehead"><div><h1>كتالوج المواد</h1><p>المستلزمات الطبية والمواد الاستهلاكية والأجهزة.</p></div>${btn('＋ إضافة مادة',"location.hash='supply/new'",'primary')}</div><div class="supply-grid">${db.stock.map(u=>`<article class="panel supply-item"><div class="row between">${ico('stock')}<small>${u.kind}</small></div><h2>${esc(u.name)}</h2><p dir="ltr">${esc(u.sku)}</p><div class="row between"><span>${u.type}</span><a href="#supply/${u.id}">تعديل المادة ←</a></div></article>`).join('')}</div>`}
function supplyForm(id){const u=db.stock.find(u=>u.id===id)||{id:'new',name:'',sku:'',type:'مستلزمات طبية',kind:'مستهلك',qty:0,min:5,expiry:'',condition:'متاح',version:0};return `<a href="#supplies">→ كتالوج المواد</a>${head(id==='new'?'إضافة مادة':'تعديل المادة','تنعكس الكميات في المخزون والمنتجات المرتبطة.',false)}<form class="panel padded editor-form" onsubmit="saveSupply(event,'${id}',${u.version})"><div class="formgrid">${inputField('اسم المادة','name',u.name,'text','required')}${inputField('رمز المادة SKU','sku',u.sku,'text','required')}<label>التصنيف<select name="type">${['مستلزمات طبية','مواد استهلاكية'].map(t=>`<option ${u.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>نوع المادة<select name="kind" onchange="document.querySelector('#equipment').hidden=this.value!=='جهاز';document.querySelector('#consumables').hidden=this.value==='جهاز'"><option ${u.kind==='مستهلك'?'selected':''}>مستهلك</option><option ${u.kind==='جهاز'?'selected':''}>جهاز</option></select></label><div class="wide formgrid" id="consumables" ${u.kind==='جهاز'?'hidden':''}>${inputField('الكمية','qty',u.qty,'number',`min="0" step="0.01" ${u.variants?.length?'readonly':''}`)}${inputField('حد تنبيه النقص','min',u.min,'number','min="0"')}${inputField('تاريخ الصلاحية','expiry',u.expiry,'date')}</div><label class="wide" id="equipment" ${u.kind!=='جهاز'?'hidden':''}>حالة الجهاز<select name="condition"><option ${u.condition==='متاح'?'selected':''}>متاح</option><option ${u.condition==='صيانة'?'selected':''}>صيانة</option></select></label></div><div class="form-actions"><button class="primary">حفظ المادة</button></div></form>`}
function saveSupply(e,id,v){e.preventDefault();if(!canStock())return;const f=Object.fromEntries(new FormData(e.target));loadLatest();const old=db.stock.find(u=>u.id===id);if(old&&old.version!==v)return toast('تغيرت المادة؛ أعيدي فتحها');if(db.stock.some(u=>u.sku===f.sku&&u.id!==id))return toast('رمز المادة مستخدم بالفعل');const u={...old,...f,id:old?.id||'u'+Date.now(),qty:+f.qty,min:+f.min,version:v+1,variants:old?.variants||[]};stockLog(u,old?.qty||0,u.qty,old?'تعديل بيانات المادة':'إضافة مادة جديدة');if(old)Object.assign(old,u);else db.stock.push(u);db.inventoryRevision++;save();location.hash='supplies';toast('تم حفظ المادة')}
let productQuery='',productStatus='all';
function productsPage(){return `<div class="pagehead"><div><h1>المنتجات</h1><p>المنتجات المعروضة وأسعارها وكمياتها، مرتبطة بسجل المخزون.</p></div>${btn('＋ منتج جديد',"productForm()",'primary')}</div><div class="product-filters"><label>البحث عن منتج<input type="search" value="${esc(productQuery)}" placeholder="اسم المنتج أو الرمز" oninput="productQuery=this.value;renderProducts()"></label><label>الحالة<select onchange="productStatus=this.value;renderProducts()">${[['all','كل المنتجات'],['active','نشط'],['archived','مؤرشف'],['empty','نفدت الكمية']].map(([v,l])=>`<option value="${v}" ${productStatus===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div id="productResults">${productResults()}</div>`}
function productResults(){const list=db.products.filter(p=>{const u=db.stock.find(u=>u.id===p.stockId);return (p.name+' '+(u?.sku||'')).toLowerCase().includes(productQuery.trim().toLowerCase())&&(productStatus==='all'||productStatus==='active'&&p.active||productStatus==='archived'&&!p.active||productStatus==='empty'&&!(u?.qty>0))});return list.length?`<div class="supply-grid">${list.map(p=>{const u=db.stock.find(u=>u.id===p.stockId);return `<article class="panel supply-item"><div class="row between">${ico('stock')}<span class="badge ${p.active?'green':'gray'}">${p.active?'نشط':'مؤرشف'}</span></div><h2>${esc(p.name)}</h2><p>${esc(p.description)||'لا يوجد وصف'}</p><small>${esc(p.category||'منتجات العناية')}</small><div class="bill-line"><span>السعر</span><strong>${money(p.price)}</strong></div><div class="bill-line"><span>الكمية المسجلة</span><strong>${u?.qty||0}</strong></div>${u?.expiry&&u.expiry<today?'<p class="badge amber">منتهي الصلاحية · غير متاح للبيع</p>':u?.qty>0?'':'<p class="badge amber">نفدت الكمية</p>'}<div class="row between"><small dir="ltr">${esc(u?.sku||'')}</small>${btn('تعديل المنتج',`productForm('${p.id}')`,'inline')}</div></article>`}).join('')}</div>`:`<div class="product-results-empty">${db.products.length?'لا توجد منتجات مطابقة للبحث أو التصفية.':'لا توجد منتجات بعد. أضيفي أول منتج لبدء الكتالوج.'}</div>`}
function renderProducts(){$('#productResults').innerHTML=productResults()}
function productStockSelection(value){const u=db.stock.find(u=>u.id===value);$('#productQty').value=u?.qty||0;$('#productSku').value=u?.sku||'';$('#productSku').readOnly=!!u;$('#productStockVersion').value=u?.version||0}
function productForm(id){const p=db.products.find(p=>p.id===id)||{name:'',description:'',price:0,stockId:'',active:true},u=db.stock.find(u=>u.id===p.stockId);modal(id?'تعديل المنتج':'إضافة منتج',`<form onsubmit="saveProduct(event,'${id||''}',${db.catalogRevision})"><div class="formgrid">${inputField('اسم المنتج','name',p.name,'text','required')}${inputField('السعر','price',p.price,'number','min="0" step="0.01" required')}${inputField('التصنيف','category',p.category||'منتجات العناية','text','required')}<label>الحالة<select name="active"><option value="true" ${p.active?'selected':''}>نشط</option><option value="false" ${!p.active?'selected':''}>مؤرشف</option></select></label><label class="wide">الوصف<textarea name="description" rows="3">${esc(p.description)}</textarea></label><label class="wide">ربط المخزون<select name="stockId" onchange="productStockSelection(this.value)"><option value="">إنشاء سجل مخزون جديد لهذا المنتج</option>${db.stock.filter(u=>u.kind!=='جهاز').map(u=>`<option value="${u.id}" ${p.stockId===u.id?'selected':''}>${esc(u.name)} · ${u.qty}</option>`).join('')}</select></label><label>رمز المنتج SKU<input id="productSku" name="sku" dir="ltr" value="${esc(u?.sku||'')}" ${u?'readonly':''} required></label><label>الكمية المسجلة<input id="productQty" name="qty" type="number" min="0" step="1" value="${u?.qty||0}" required></label><input type="hidden" id="productStockVersion" name="stockVersion" value="${u?.version||0}"><label class="wide">سبب تغيير الكمية<input name="reason" placeholder="مثال: توريد جديد أو تصحيح جرد"></label></div><p class="product-quantity-note">تغيير كمية مادة مرتبطة ينعكس على المخزون وكل المنتجات المرتبطة بها، ويُسجّل في السجل.</p><p id="productError" role="alert"></p><div class="footer"><button class="primary">حفظ المنتج</button></div></form>`)}
function saveProduct(e,id,revision){e.preventDefault();if(!canStock())return;const f=Object.fromEntries(new FormData(e.target));loadLatest();const fail=t=>$('#productError').textContent=t;if(db.catalogRevision!==revision)return fail('تغير الكتالوج؛ أعيدي فتح النموذج قبل الحفظ.');let u=db.stock.find(u=>u.id===f.stockId);const qty=Number(f.qty);if(!Number.isInteger(qty)||qty<0)return fail('أدخلي كمية صحيحة لا تقل عن صفر.');if(u&&u.version!==Number(f.stockVersion))return fail('تغيرت كمية المخزون؛ أعيدي فتح النموذج قبل الحفظ.');if(u&&u.qty!==qty&&!f.reason.trim())return fail('اكتبي سبب تغيير الكمية لتوثيقه في السجل.');if(!u){if(!f.sku.trim()||db.stock.some(x=>x.sku===f.sku.trim()))return fail('أدخلي رمز منتج جديدًا وغير مستخدم.');u={id:'u'+Date.now(),name:f.name,sku:f.sku.trim(),type:'مواد استهلاكية',kind:'مستهلك',qty,min:0,expiry:'',version:1,variants:[]};db.stock.push(u);stockLog(u,0,qty,'إضافة مخزون منتج جديد');db.inventoryRevision++}else if(u.qty!==qty){stockLog(u,u.qty,qty,f.reason);u.qty=qty;u.version++;db.inventoryRevision++}const old=db.products.find(p=>p.id===id),p={...old,id:id||'p'+Date.now(),name:f.name.trim(),description:f.description,category:f.category,price:Number(f.price),active:f.active==='true',stockId:u.id};if(old)Object.assign(old,p);else db.products.push(p);db.catalogRevision++;save();closeModal();render();toast('تم حفظ المنتج وتحديث المخزون')}
catalog=function(){let html=originalCatalog();if(canStock())html=html.replace('</h1>','</h1>').replace('<div class="pagehead">','<div class="catalog-actions">'+btn('＋ إضافة خدمة',"location.hash='service-edit/new'",'primary')+'</div><div class="pagehead">');return html};
servicePage=function(id){let html=originalServicePage(id);if(canStock()){const s=services[id];return `<a href="#services">→ الخدمات</a>${head(esc(s.name),s.cat,false)}<section class="panel padded"><div class="row between"><h2>تفاصيل الخدمة</h2>${btn('تعديل الخدمة',`location.hash='service-edit/${id}'`,'primary')}</div><p>${esc(s.description)}</p><div class="facts section"><div><small>السعر</small>${money(s.price)}</div><div><small>المدة</small>${s.duration} دقيقة</div><div><small>وقت التحضير</small>${s.prep||5} دقائق</div><div><small>وقت التجهيز بعد الجلسة</small>${s.buffer||10} دقائق</div></div><div class="section">${avail(s)}</div></section>`}return html};
function serviceEditor(id){const s=services[id]||{name:'',cat:'العناية بالبشرة',price:0,duration:30,description:'',availability:'available',prep:5,buffer:10,active:true};return `<a href="#services">→ الخدمات</a>${head(id==='new'?'إضافة خدمة':'تعديل الخدمة','تسري التعديلات على الحجوزات الجديدة.',false)}<form class="editor-form" onsubmit="saveService(event,'${id}',${db.catalogRevision})"><section class="panel padded"><h2>المعلومات الأساسية</h2><div class="formgrid">${inputField('اسم الخدمة','name',s.name,'text','required')}<label>التصنيف<select name="cat">${[...new Set(services.map(s=>s.cat))].map(c=>`<option ${s.cat===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="wide">الوصف<textarea name="description">${esc(s.description)}</textarea></label><label class="wide">صورة الخدمة (اختياري، أقل من 1MB)<input name="image" type="file" accept="image/*"></label></div>${s.image?`<img class="service-image" src="${esc(s.image)}" alt="${esc(s.name)}">`:''}</section><section class="panel padded"><h2>السعر والمدة</h2><div class="formgrid">${inputField('السعر الأساسي','price',s.price,'number','min="0" step="0.01" required')}${inputField('سعر التخفيض (اختياري)','discount',s.discount??'','number','min="0" step="0.01"')}${inputField('مدة الجلسة بالدقائق','duration',s.duration,'number','min="5" step="5" required')}${inputField('وقت التحضير','prep',s.prep||5,'number','min="0" step="5"')}${inputField('وقت التنظيف / التجهيز','buffer',s.buffer||10,'number','min="0" step="5"')}</div><details class="editor-disclosure"><summary>خيارات الخدمة</summary><div id="serviceVariants">${(s.variants||[]).map(v=>variantEditorRow(v)).join('')}</div><button type="button" onclick="document.querySelector('#serviceVariants').insertAdjacentHTML('beforeend',variantEditorRow())">＋ إضافة خيار</button></details></section><section class="panel padded"><h2>إتاحة الحجز</h2><div class="formgrid"><label>الحالة<select name="availability">${[['available','متاحة'],['review','مراجعة الطبيبة مطلوبة'],['unavailable','غير متاحة مؤقتًا']].map(([v,t])=>`<option value="${v}" ${s.availability===v?'selected':''}>${t}</option>`).join('')}</select></label><label>عرض الخدمة<select name="active"><option value="true" ${s.active!==false?'selected':''}>نشطة</option><option value="false" ${s.active===false?'selected':''}>مؤرشفة</option></select></label></div><p class="muted section">المتطلبات الطبية وتعليمات العناية تعتمدها جيجي.</p>${role==='doctor'?`<details class="editor-disclosure"><summary>المتطلبات الطبية والعناية</summary><label>تعليمات العناية<textarea name="aftercare">${esc(s.aftercare||'')}</textarea></label>${inputField('المتابعة الموصى بها بعد أيام','followup',s.followup||14,'number','min="0"')}</details>`:''}</section><div class="form-actions"><button class="primary">حفظ الخدمة</button><a href="#services">إلغاء</a></div></form>`}
function variantEditorRow(v={name:'',price:0,duration:30}){return `<div class="service-variant-row">${inputField('اسم الخيار','vname',v.name,'text','required')}${inputField('السعر','vprice',v.price,'number','min="0" required')}${inputField('المدة','vduration',v.duration,'number','min="5" required')}<button type="button" aria-label="حذف الخيار" onclick="this.parentElement.remove()">×</button></div>`}
async function saveService(e,id,revision){e.preventDefault();if(!canStock())return;const form=e.target,f=new FormData(form);if(f.get('discount')&&+f.get('discount')>+f.get('price'))return toast('سعر التخفيض يجب ألا يتجاوز السعر الأساسي');const old=services[id];let image=old?.image||'';const file=f.get('image');if(file?.size){if(file.size>1000000||!file.type.startsWith('image/'))return toast('اختاري صورة أصغر من 1MB');image=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file)})}loadLatest();if(db.catalogRevision!==revision)return toast('تغير الكتالوج؛ أعيدي فتح الخدمة قبل الحفظ');const s={...old,id:old?.id??services.length,name:f.get('name'),cat:f.get('cat'),description:f.get('description'),price:+f.get('price'),duration:+f.get('duration'),prep:+f.get('prep'),buffer:+f.get('buffer'),discount:f.get('discount')?+f.get('discount'):null,availability:f.get('availability'),active:f.get('active')==='true',image,variants:[...form.querySelectorAll('.service-variant-row')].map(row=>({name:row.querySelector('[name=vname]').value,price:+row.querySelector('[name=vprice]').value,duration:+row.querySelector('[name=vduration]').value}))};if(role==='doctor'){s.aftercare=f.get('aftercare')||old?.aftercare||'';s.followup=+(f.get('followup')||14)}if(old)services[id]=s;else services.push(s);db.catalogRevision++;save();location.hash='services';toast('تم حفظ الخدمة')}
function adminPage(){return head('إدارة العيادة','إدارة جيجي للصلاحيات وعمليات الفريق.',false)+`<section class="panel padded"><h2>فريق Nothing Major</h2><div class="team-cards">${Object.entries(roles).map(([id,r])=>`<article><span class="avatar">${r.initial}</span><h3>${r.name}</h3><p>${r.title}</p><small>${id==='reception'?'إدارة المواعيد، الوصول، الدفع، ودردشة العميلات':'الجلسات والملفات الطبية والمراجعات وإدارة المخزون والمنتجات والعيادة'}</small></article>`).join('')}</div></section><section class="panel padded"><h2>طلبات تحتاج قرارك</h2>${db.appointments.filter(a=>a.review||a.decisionRequested).map(a=>`<div class="bill-line"><span>${esc(a.name)}<small>${a.review?'مراجعة طبية مطلوبة':'طلب استثناء من الاستقبال'}</small></span><a href="#appointment/${a.id}">مراجعة ←</a></div>`).join('')||'<p>لا توجد طلبات معلقة.</p>'}</section>`}
function toggleChat(){if($('#chatPanel').hidden){$('#chatPanel').hidden=false;drawChat()}else closeChat()}function closeChat(){if($('#chatPanel'))$('#chatPanel').hidden=true}
function drawChat(){const patients=[...new Map(db.appointments.map(a=>[a.phone,a])).values()];if(!chatId||!patients.some(a=>a.phone===chatId))chatId=patients[0]?.phone;const a=patients.find(a=>a.phone===chatId);$('#chatPanel').innerHTML=`<div class="chat-heading"><div>${ico('chat')}<strong>دردشة العميلات</strong></div><button class="ghost" aria-label="إغلاق الدردشة" onclick="closeChat()">×</button></div><div class="chat-demo">معاينة تجريبية · الرسائل محفوظة محليًا ولا تُرسل فعليًا</div><label class="chat-picker">العميلة<select onchange="chatId=this.value;drawChat()">${patients.map(p=>`<option value="${p.phone}" ${p.phone===chatId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="chat-messages" id="chatMessages"><div class="chat-intro"><span class="avatar">${esc(a?.name[0]||'')}</span><strong>${esc(a?.name||'')}</strong><span dir="ltr">${chatId||''}</span></div>${(db.messages[chatId]||[]).map(m=>`<div class="chat-bubble"><p>${esc(m.text)}</p><small>${m.actor} · ${m.time} · محفوظة تجريبيًا</small></div>`).join('')}</div><button class="reminder" onclick="draftReminder()">${ico('calendar')}كتابة تذكير بالموعد</button><form class="chat-composer" onsubmit="sendChat(event)"><textarea name="message" id="chatInput" rows="2" placeholder="اكتبي رسالة…" required aria-label="نص الرسالة"></textarea><button class="primary" aria-label="إرسال تجريبي">←</button></form>`}
function draftReminder(){const a=db.appointments.filter(a=>a.phone===chatId&&a.status!=='cancelled').sort((a,b)=>b.date.localeCompare(a.date))[0];$('#chatInput').value=`مرحبًا ${a.name}، نذكرك بموعدك في عيادة Nothing Major يوم ${fmt(a.date)} الساعة ${a.time}. نرجو الحضور قبل الموعد بـ 10 دقائق. يسعدنا تواصلك لتأكيد الحضور.`;$('#chatInput').focus()}
function sendChat(e){e.preventDefault();if(!['reception','doctor'].includes(role))return;const text=new FormData(e.target).get('message').trim();if(!text)return;loadLatest();db.messages[chatId]??=[];db.messages[chatId].push({text,actor:actor(),time:now()});save();drawChat();toast('حُفظت الرسالة في الدردشة التجريبية')}
render=function(){let r=location.hash.slice(1)||'home';if(!canStock()&&/^(inventory|products|supplies|supply|variants|service-edit)/.test(r)){location.hash='home';r='home'}if(role!=='doctor'&&/^(session|medical|admin)/.test(r)){location.hash='home';r='home'}if(r==='admin'&&!admin){location.hash='home';r='home'}shellTeam();const [p,id]=r.split('/');const map={home,appointments:calendar,services:catalog,service:()=>servicePage(+id),appointment:()=>detail(id),session:()=>sessionPage(id),medical:()=>medicalPage(id),inventory:()=>id==='count'?countPage():id==='history'?historyPage():stockPage(),supplies:suppliesPage,supply:()=>supplyForm(id),variants:()=>variantsPage(id),products:productsPage,'service-edit':()=>serviceEditor(id),admin:adminPage};$('#main').innerHTML=(map[p]||home)();if(p==='home'&&role==='doctor'){const old=db.appointments.filter(a=>a.status==='session'&&a.date<today);if(old.length)$('#main').insertAdjacentHTML('afterbegin',`<section class="notice"><strong>جلسات سابقة تحتاج مراجعة</strong><p>لم يُسجّل إنهاؤها؛ لا تمنع بدء مواعيد اليوم.</p>${old.map(a=>`<a class="review-old" href="#session/${a.id}">${esc(a.name)} · ${fmt(a.date)} ← مراجعة الجلسة</a>`).join('')}</section>`);}if(p==='appointments'&&!canReception())$('#main .pagehead .primary')?.remove();filterStockRows();tickTimer();document.title='Clinime · '+roles[role].name};
// Restrict operational controls to the active prototype persona.
for(const name of ['checkin','reschedule','cancelBooking','checkout','deposit','confirmBooking']){const original=window[name];window[name]=function(...args){if(!canReception()){toast('هذا الإجراء ضمن صلاحيات الاستقبال أو وضع الإدارة');return}return original(...args)}}
render();

const receptionVisitAction=visitAction;visitAction=function(a){return role==='doctor'?btn('عرض الموعد',`location.hash='appointment/${a.id}'`,'inline'):receptionVisitAction(a)};
